{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "N-methyl-salsolinol, a small basic heterocycle with a methylated pyrrolidine-like amine, easily penetrated the BBB in rats with sustained brain levels, supporting CNS access for the query's basic pyrrolidine-heteroaryl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "[11C]ABT-418, a pyrrolidine-containing heteroaromatic ligand, showed rapid and substantial brain uptake on PET in monkeys, demonstrating that this structural class crosses the BBB effectively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Nicotine, a tertiary-amine pyrrolidine heteroaromatic, exhibited high brain uptake index and rapid brain entry across multiple rodent models, supporting high passive CNS penetration for the query's similar pyrrolidine-heteroaromatic framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A-582941, a pyrrolidine-containing heteroaryl, showed high brain uptake in mice, providing direct evidence that related pyrrolidine-heteroaromatic compounds achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "SHP099, an amino-substituted heteroaromatic with a basic saturated amine, achieved brain-to-plasma ratios >1 in mice, showing that polar amino/nitrile heteroaromatic features do not preclude meaningful brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "MS-153, a small heteroaromatic compound, reached CSF concentrations nearly equal to plasma, supporting meaningful CNS access for small heteroaromatic molecules with multiple polar atoms.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues demonstrate meaningful CNS access for small basic pyrrolidine-heteroaromatic compounds, including direct brain uptake, PET, CSF, and brain-to-plasma measurements. The query shares the key tertiary-amine pyrrolidine and heteroaromatic features, and no evidence points to inadequate BBB penetration.",
  "evidence_gaps": [
    "No direct experimental measurement of the query molecule's brain or CSF exposure is available.",
    "No explicit P-gp/BCRP efflux data for the query or its closest analogues is provided.",
    "Unbound brain-to-plasma partitioning for the query is not directly known, though the evidence supports meaningful total CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

